(function () {
window.AINOW = window.AINOW || {};
var __exports = AINOW['data/data-dataanalysis'] = AINOW['data/data-dataanalysis'] || {};
const dataanalysisPrompts = [

  // --- 1. EXPLORATORY DATA ANALYSIS (da-1 to da-10) ---
  {"id":"da-1","title":"EDA on Customer Transaction Data","prompt":"You are a senior data analyst at a 500-person subscription SaaS company. Your stack is Python with pandas, matplotlib, seaborn, and Jupyter notebooks. You have just received a new customer transaction dataset before any modeling work begins. Write a complete EDA script that computes descriptive statistics (mean, median, std, skewness, kurtosis) for all numeric columns, plots univariate distributions using seaborn histplots with KDE overlays, generates a Pearson correlation heatmap, and uses the IQR method to flag outliers in the monthly_spend and session_count columns. The script should produce a final printed summary of columns with more than 5% null values and a list of detected outlier row indices.","tags":["eda","python","pandas","distributions","outliers"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"da-2","title":"Feature Relationship Analysis for Churn Prediction","prompt":"You are a data scientist at a 300-person B2B fintech company building a customer churn prediction model. Your tools are Python, pandas, seaborn, and scipy. Before feature selection, you need to understand relationships between candidate predictors and the binary churn label. Write a Python script that computes point-biserial correlation between each continuous feature and the churn column, generates grouped violin plots for the top 5 correlated features split by churn status, and runs a chi-squared test for each categorical feature against churn. Output a ranked DataFrame showing feature name, correlation coefficient or chi-squared statistic, and p-value, sorted by absolute effect size descending.","tags":["eda","feature-analysis","churn","scipy","seaborn"],"author":"AINOW","created":"2024-02-15T10:05:00Z","featured":false},

  {"id":"da-3","title":"Distribution Shift Detection Across Weekly Cohorts","prompt":"You are a growth analyst at a direct-to-consumer e-commerce brand processing roughly 50,000 orders per week. You use Python and pandas to maintain a weekly reporting pipeline. You have noticed that the average order value reported last week seems unusually high and suspect a distribution shift in the order_value column between cohort weeks. Write a Python function that takes two pandas Series (current week and prior week), computes the Kolmogorov-Smirnov test statistic and p-value using scipy.stats.ks_2samp, plots overlapping ECDF curves with matplotlib, and prints a plain-English verdict: whether the distributions are significantly different at the 0.05 alpha level and what the practical implication is for the weekly revenue report.","tags":["eda","distribution-shift","ks-test","scipy","matplotlib"],"author":"AINOW","created":"2024-02-15T10:10:00Z","featured":false},

  {"id":"da-4","title":"Multivariate Outlier Detection with Isolation Forest","prompt":"You are a fraud analytics engineer at a payments company handling 2 million transactions per month. Your Python environment includes scikit-learn, pandas, and matplotlib. Univariate IQR-based outlier detection is missing coordinated fraud patterns that only appear when multiple signals are combined. Write a Python script that trains an IsolationForest model (contamination=0.01, random_state=42) on a feature matrix of transaction_amount, velocity_24h, country_risk_score, and device_age_days, adds a predicted anomaly_flag column to the original DataFrame, and produces a 2D scatter plot using PCA-reduced coordinates that highlights flagged transactions in red. Include a comment explaining how to tune the contamination parameter based on known fraud rate.","tags":["eda","outlier-detection","isolation-forest","scikit-learn","fraud"],"author":"AINOW","created":"2024-02-15T10:15:00Z","featured":false},

  {"id":"da-5","title":"Missing Data Pattern Analysis Before Imputation","prompt":"You are a data analyst at a 150-person healthcare technology company. Your workflow uses Python, pandas, and the missingno library. You have received a clinical trial dataset with 120 columns and 8,000 rows where missingness may not be random — certain lab values are only missing for patients who dropped out early. Write a Python script that uses missingno.matrix() and missingno.heatmap() to visualize nullity patterns, computes the percentage of missing values per column, runs Little's MCAR test using the pyampute library to determine whether data is Missing Completely at Random, and produces a final recommendation table distinguishing columns suitable for mean/median imputation versus those requiring multiple imputation or deletion, based on missingness percentage thresholds of 5%, 20%, and 40%.","tags":["eda","missing-data","imputation","missingno","data-quality"],"author":"AINOW","created":"2024-02-15T10:20:00Z","featured":false},

  {"id":"da-6","title":"Time-Series EDA for Retail Sales Seasonality","prompt":"You are a senior analyst at a 1,200-person omnichannel retail company. You use Python with pandas, statsmodels, and matplotlib to support the demand planning team. Before building a sales forecast, you need to characterize seasonality and trend in four years of weekly store-level sales data. Write a Python script that decomposes the weekly sales time series using statsmodels seasonal_decompose with model='multiplicative', plots the trend, seasonal, and residual components, computes and plots the autocorrelation function (ACF) and partial autocorrelation function (PACF) out to 52 lags, and identifies the dominant seasonal period. Output a written interpretation of what the ACF/PACF plots suggest about appropriate AR and MA orders for a subsequent SARIMA model.","tags":["eda","time-series","seasonality","statsmodels","acf-pacf"],"author":"AINOW","created":"2024-02-15T10:25:00Z","featured":false},

  {"id":"da-7","title":"Categorical Variable Profiling for a Marketing Dataset","prompt":"You are a CRM analyst at a 400-person insurance company using Python and pandas. You have received a leads dataset with 15 categorical columns including product_interest, lead_source, agent_region, and coverage_tier before building a propensity-to-purchase model. Write a Python function that accepts a DataFrame and a list of categorical column names and for each column: prints value counts with percentage share, flags categories with fewer than 1% frequency as candidates for grouping into an 'Other' bucket, computes Cramér's V statistic against the binary converted label, and generates a horizontal bar chart sorted by frequency. Return a summary DataFrame with column name, cardinality, top category share, and Cramér's V score.","tags":["eda","categorical","cramers-v","profiling","pandas"],"author":"AINOW","created":"2024-02-15T10:30:00Z","featured":false},

  {"id":"da-8","title":"High-Cardinality ID Column Audit","prompt":"You are a data engineer at a 250-person logistics startup. Your stack is Python, pandas, and BigQuery. A new data source from a third-party carrier has been ingested into the warehouse and you need to audit its key columns before joining it to internal tables. Write a Python script that loads a sample of 100,000 rows and for each potential join key column (shipment_id, carrier_tracking_number, origin_zip): computes uniqueness ratio (distinct count divided by total rows), detects leading/trailing whitespace and mixed-case inconsistencies, checks for non-standard formats using regex patterns (e.g. ZIP codes not matching \\d{5}), and flags columns that fail a referential integrity check against the internal shipments table. Produce a concise audit report DataFrame with a PASS/FAIL verdict for each column.","tags":["eda","data-audit","referential-integrity","pandas","bigquery"],"author":"AINOW","created":"2024-02-15T10:35:00Z","featured":false},

  {"id":"da-9","title":"Exploratory Cohort Comparison for A/B Test Pre-Check","prompt":"You are a product analyst at a 180-person mobile gaming company using Python, pandas, and seaborn. Before declaring the results of a 14-day A/B test on a new onboarding flow, you need to verify that the control and treatment groups were balanced at assignment time. Write a Python script that compares the two groups across five pre-experiment covariates: device_os, country_tier, account_age_days, prior_7d_sessions, and prior_7d_spend. For continuous variables run a two-sample t-test and report the p-value; for categorical variables run a chi-squared test. Generate a balance table in the style of academic RCT papers, showing mean or proportion for each group, the test statistic, p-value, and a BALANCED or IMBALANCED flag at the 0.05 significance level.","tags":["eda","ab-test","balance-check","cohort","statistics"],"author":"AINOW","created":"2024-02-15T10:40:00Z","featured":false},

  {"id":"da-10","title":"Automated EDA Report with ydata-profiling","prompt":"You are a data analyst at a 600-person retail bank's credit risk team. Your Python environment includes ydata-profiling, pandas, and Jupyter. A new batch of loan application data arrives monthly and requires a standardized EDA report before any analyst touches it. Write a Python script that loads the monthly CSV, initializes a ProfileReport with explorations for correlations, missing values, duplicates, and warnings, configures the report to use the dark theme and enable the interactions tab for pairwise scatter plots between loan_amount, annual_income, credit_score, and debt_to_income_ratio, exports the report to an HTML file named with the current date, and prints a console summary of the top 5 warnings (e.g. high cardinality, high correlation, many missing values) that require analyst review before proceeding.","tags":["eda","ydata-profiling","automation","credit-risk","reporting"],"author":"AINOW","created":"2024-02-15T10:45:00Z","featured":false},

  // --- 2. SQL & DATABASE QUERIES (da-11 to da-20) ---
  {"id":"da-11","title":"Customer LTV Ranking with Window Functions","prompt":"You are a data analyst at a 350-person e-commerce company using BigQuery. The finance team needs a ranked list of customers by lifetime value within each acquisition channel so they can allocate retention budget. Write a BigQuery SQL query that uses a CTE to aggregate total revenue and order count per customer from the orders table, then applies RANK() OVER (PARTITION BY acquisition_channel ORDER BY lifetime_revenue DESC) to rank customers within each channel, and finally filters to return only the top 10 customers per channel. Include the customer_id, email_domain, acquisition_channel, lifetime_revenue, order_count, average_order_value, and channel_rank columns. Add inline comments explaining the window function partitioning logic.","tags":["sql","bigquery","window-functions","ltv","ranking"],"author":"AINOW","created":"2024-02-15T10:50:00Z","featured":false},

  {"id":"da-12","title":"Signup Funnel Drop-Off Query in Snowflake","prompt":"You are a product data analyst at a 200-person SaaS company using Snowflake. The product team wants to understand where users drop out of the five-step signup funnel: page_view, account_created, email_verified, plan_selected, payment_completed. Write a Snowflake SQL query using CTEs that pivots the events table (columns: user_id, event_name, event_timestamp) into one row per user showing the maximum timestamp for each funnel step, computes the conversion rate from each step to the next as a percentage, and calculates median time-to-completion in minutes for users who reached each step. Return one summary row per funnel step with step_name, users_reached, conversion_rate_pct, and median_minutes_to_step columns, ordered by funnel position.","tags":["sql","snowflake","funnel","cte","product-analytics"],"author":"AINOW","created":"2024-02-15T10:55:00Z","featured":false},

  {"id":"da-13","title":"Slow Query Optimization Review","prompt":"You are a senior analytics engineer at a 700-person media company whose PostgreSQL reporting database is showing query times above 30 seconds on a dashboard that refreshes every 15 minutes. [Paste your SQL query] Review the query above and rewrite it to improve performance. Specifically: replace any correlated subqueries with CTEs or lateral joins, add appropriate index hints or suggest which composite indexes to create on the base tables, eliminate redundant DISTINCT operations where a GROUP BY would suffice, and push filter predicates as early as possible in the query plan. Provide the rewritten query and a bullet-point explanation of each optimization applied, including the expected improvement in execution plan cost based on standard PostgreSQL query planner behavior.","tags":["sql","optimization","postgresql","execution-plan","performance"],"author":"AINOW","created":"2024-02-15T11:00:00Z","featured":false},

  {"id":"da-14","title":"Rolling 28-Day Active User Metric in BigQuery","prompt":"You are a growth analyst at a 120-person mobile app company using BigQuery. The north star metric is Monthly Active Users defined as any user with at least one app_open event in the last 28 days, computed daily. Write a BigQuery SQL query that uses a date spine CTE to generate every calendar date for the past 90 days, joins it to the app_events table to find each user's distinct active dates, and uses a window function approach with COUNTIF and a RANGE BETWEEN 27 PRECEDING AND CURRENT ROW window frame to compute the rolling 28-day unique user count for each date. The query should run efficiently on a 500 million row events table by partitioning on event_date and clustering on user_id.","tags":["sql","bigquery","rolling-metrics","mau","window-functions"],"author":"AINOW","created":"2024-02-15T11:05:00Z","featured":false},

  {"id":"da-15","title":"Recursive CTE for Org Hierarchy Path","prompt":"You are a people analytics engineer at a 2,000-person company using SQL Server. HR leadership needs a report showing the full management chain from every individual contributor up to the CEO, expressed as a single delimited path string like 'CEO > VP Eng > Director > Manager > IC'. Write a SQL Server recursive CTE that starts from the anchor member (the CEO row where manager_id IS NULL), iterates through each level of the employees table (columns: employee_id, full_name, manager_id, department, level), builds a path string by concatenating names with ' > ', tracks the depth level as an integer, and terminates at leaf nodes. Return employee_id, full_name, department, hierarchy_depth, and full_path for all employees, ordered by department and hierarchy_depth.","tags":["sql","recursive-cte","sql-server","hr-analytics","hierarchy"],"author":"AINOW","created":"2024-02-15T11:10:00Z","featured":false},

  {"id":"da-16","title":"Multi-Touch Attribution Side-by-Side Comparison","prompt":"You are a marketing data analyst at a 450-person B2C subscription company using Redshift. The CMO wants to compare first-touch, last-touch, and linear attribution models side-by-side for the last quarter's paid campaigns. Write a Redshift SQL query using CTEs that: first identifies all converting users from the conversions table, then joins to the touchpoints table to retrieve their full pre-conversion marketing touchpoint history ordered by touchpoint_timestamp, then applies three separate attribution calculations — 100% credit to the first touchpoint, 100% to the last, and equal fractional credit across all touchpoints for linear — and finally aggregates attributed revenue by campaign_name and channel under each model. Return a wide result with one row per campaign showing revenue under all three attribution models side by side.","tags":["sql","redshift","attribution","marketing","cte"],"author":"AINOW","created":"2024-02-15T11:15:00Z","featured":false},

  {"id":"da-17","title":"Dead Stock Identification for Wholesale Distribution","prompt":"You are a supply chain analyst at a 900-person wholesale distributor using Databricks SQL. The operations team needs to identify slow-moving SKUs that have been in the warehouse for more than 90 days and have a stock-to-sales ratio above 6x. Write a Databricks SQL query that joins the inventory_snapshots table (sku_id, warehouse_id, units_on_hand, snapshot_date) with the sales_transactions table (sku_id, units_sold, transaction_date) using a CTE to compute average daily units sold over the last 30 days per SKU, then calculates days_of_supply as units_on_hand divided by avg_daily_sales, flags SKUs where days_of_supply exceeds 90 and avg_daily_sales is below 0.5 units as dead_stock, and returns the result with estimated_holding_cost assuming $0.15 per unit per day.","tags":["sql","databricks","inventory","supply-chain","dead-stock"],"author":"AINOW","created":"2024-02-15T11:20:00Z","featured":false},

  {"id":"da-18","title":"Monthly Cohort Retention Matrix Query","prompt":"You are a data analyst at a 160-person mobile fitness app company using BigQuery. The head of product wants a monthly cohort retention matrix showing what percentage of users who signed up in each calendar month are still active 1, 2, 3, 6, and 12 months later. Write a BigQuery SQL query that defines user cohorts by their signup_month using DATE_TRUNC on the created_at column from the users table, joins to the sessions table to find each user's active months, calculates months_since_signup as the integer difference between activity_month and cohort_month, pivots the result using conditional aggregation to show retention rates at each interval as percentages of the original cohort size, and returns the matrix ordered by cohort_month ascending with NULL for intervals not yet elapsed.","tags":["sql","bigquery","cohort","retention","product-analytics"],"author":"AINOW","created":"2024-02-15T11:25:00Z","featured":false},

  {"id":"da-19","title":"Duplicate Detection and Safe Quarantine Query","prompt":"You are a data quality engineer at a 280-person insurtech company using PostgreSQL. A third-party data provider has been ingesting policy application records and the team suspects duplicate submissions are inflating the conversion rate metric by 8-12%. Write a PostgreSQL SQL query that uses a CTE with ROW_NUMBER() OVER (PARTITION BY first_name, last_name, date_of_birth, postal_code, product_type ORDER BY submission_timestamp ASC) to identify duplicate application records, labels the earliest submission as the canonical record and all subsequent ones as duplicates, produces a summary showing total records, distinct canonical records, duplicate count, and duplication rate as a percentage, and generates a DELETE-safe staging query that moves duplicates to a quarantine_applications table rather than hard-deleting them.","tags":["sql","postgresql","deduplication","data-quality","row-number"],"author":"AINOW","created":"2024-02-15T11:30:00Z","featured":false},

  {"id":"da-20","title":"Dynamic Pricing Percentile Benchmarking","prompt":"You are a pricing analyst at a 550-person online marketplace using Snowflake. The pricing team wants to benchmark each active listing's price against the 10th, 25th, 50th, 75th, and 90th percentile prices for listings in the same category and condition tier, updated daily. Write a Snowflake SQL query that uses PERCENTILE_CONT with WITHIN GROUP (ORDER BY list_price) inside window functions partitioned by category_id and condition_tier to compute all five percentile benchmarks, then adds columns showing each listing's price position relative to the median as a ratio, a competitive_position label (Underpriced, Market, or Overpriced) based on whether the price falls below the 25th, between 25th and 75th, or above the 75th percentile, and the estimated revenue impact of moving an underpriced listing to the median price.","tags":["sql","snowflake","percentile","pricing","window-functions"],"author":"AINOW","created":"2024-02-15T11:35:00Z","featured":false},

  // --- 3. STATISTICAL ANALYSIS (da-21 to da-30) ---
  {"id":"da-21","title":"A/B Test Analysis with Power Calculation","prompt":"You are a senior data scientist at a 300-person e-commerce company running a 21-day A/B test on a new checkout page design. Your test hypothesis is that the new design increases the checkout completion rate above the current 3.2% baseline. Using Python with scipy.stats and statsmodels, write a complete analysis script that: computes the observed conversion rates and absolute lift for control and treatment groups, runs a two-proportion z-test using proportions_ztest from statsmodels.stats.proportion, calculates the 95% confidence interval for the difference in proportions, performs a post-hoc power analysis using the observed effect size and sample size to confirm whether the test was adequately powered (target power 0.80, alpha 0.05), and outputs a verdict table with the p-value, confidence interval, observed power, and a plain-English recommendation on whether to ship the new design.","tags":["statistics","ab-testing","scipy","power-analysis","hypothesis-testing"],"author":"AINOW","created":"2024-02-15T11:40:00Z","featured":true},

  {"id":"da-22","title":"OLS Multiple Regression for Marketing Mix Analysis","prompt":"You are a marketing analyst at a 400-person consumer goods company. The CMO wants to understand which advertising channels (TV_spend, digital_spend, radio_spend, out_of_home_spend) drive weekly sales after controlling for price_index and promotional_events. Using Python with statsmodels OLS, write a script that builds a multiple linear regression model predicting weekly_sales from the five predictor variables, checks OLS assumptions by computing VIF scores for multicollinearity (flag VIF above 5), plots residuals vs. fitted values and a QQ plot for normality, reports the model summary including R-squared, adjusted R-squared, and coefficient p-values, and interprets the coefficient for digital_spend in plain English including its 95% confidence interval. Include a recommendation on whether to log-transform spend variables given typical right-skewed advertising data.","tags":["statistics","regression","statsmodels","marketing-mix","ols"],"author":"AINOW","created":"2024-02-15T11:45:00Z","featured":false},

  {"id":"da-23","title":"Bayesian A/B Test for Low-Traffic Experiments","prompt":"You are a data scientist at a 90-person SaaS startup running an A/B test on a new pricing page. With only 400 users per variant over 30 days, frequentist methods are underpowered. Using Python with the scipy.stats Beta distribution, write a Bayesian A/B test analysis that models conversion rates for both variants using Beta(1,1) priors, draws 100,000 samples from the posterior distributions using Monte Carlo simulation, computes the probability that treatment beats control (P(theta_B > theta_A)), calculates the expected loss of choosing the wrong variant, plots both posterior distributions on the same chart with a shaded overlap region, and provides a decision recommendation using a minimum detectable effect threshold of 0.5 percentage points and a 95% probability-to-beat threshold.","tags":["statistics","bayesian","ab-testing","monte-carlo","probability"],"author":"AINOW","created":"2024-02-15T11:50:00Z","featured":false},

  {"id":"da-24","title":"Kaplan-Meier Survival Analysis for Subscription Churn","prompt":"You are a retention analyst at a 500-person subscription software company using Python with lifelines. The customer success team wants to understand how long customers survive before churning, segmented by onboarding_type (self-serve vs. high-touch) and initial_plan_tier (starter vs. professional vs. enterprise). Write a Python script using the lifelines library that fits a KaplanMeierFitter for each segment combination, plots all survival curves on a single chart with confidence intervals, performs a log-rank test between self-serve and high-touch onboarding types to determine if the survival functions are statistically different at the 0.05 level, computes the median survival time and 12-month survival probability for each segment, and summarizes the business implication: which segment churns fastest and what the revenue impact is if the self-serve median survival time increased by 30 days.","tags":["statistics","survival-analysis","kaplan-meier","churn","lifelines"],"author":"AINOW","created":"2024-02-15T11:55:00Z","featured":false},

  {"id":"da-25","title":"Chi-Squared Test for Campaign Response Segmentation","prompt":"You are a CRM analyst at a 250-person financial services firm using Python and scipy. The marketing team ran an email campaign across four customer segments (High Value, Mid Value, Low Value, Dormant) and wants to know whether response rates differ significantly across segments or whether differences are due to chance. Write a Python analysis that constructs a 4x2 contingency table of segment by response (responded vs. did not respond) from raw campaign data, runs scipy.stats.chi2_contingency and reports the chi-squared statistic, degrees of freedom, p-value, and expected frequencies table, computes Cramér's V to quantify the strength of association, performs pairwise post-hoc tests with Bonferroni correction to identify which specific segment pairs differ significantly, and visualizes the observed vs. expected response rates as a grouped bar chart with error bars representing 95% confidence intervals.","tags":["statistics","chi-squared","segmentation","scipy","cramers-v"],"author":"AINOW","created":"2024-02-15T12:00:00Z","featured":false},

  {"id":"da-26","title":"Bootstrap Confidence Intervals Across Retail Regions","prompt":"You are a business analyst at a 1,100-person retail chain using Python with numpy and scipy. Regional managers are disputing whether average transaction values differ meaningfully across the Northeast, Southeast, Midwest, and West regions. Write a Python script that computes bootstrap 95% confidence intervals for the mean transaction value in each region using 10,000 bootstrap resamples (numpy random seed 42), plots the confidence intervals as a horizontal forest plot with dots at the point estimate and horizontal lines for the interval bounds, runs a one-way ANOVA to test whether at least one region mean differs (report F-statistic and p-value), and if significant, runs Tukey's HSD post-hoc test using statsmodels to identify which region pairs are significantly different. Translate the findings into a one-paragraph regional performance narrative for the operations review deck.","tags":["statistics","confidence-intervals","bootstrap","anova","scipy"],"author":"AINOW","created":"2024-02-15T12:05:00Z","featured":false},

  {"id":"da-27","title":"Logistic Regression Lead Scoring with Odds Ratios","prompt":"You are a revenue operations analyst at a 220-person B2B software company using Python with statsmodels. Sales needs a statistically grounded lead score that can be explained to account executives, not just a black-box ML model. Write a Python script that fits a logistic regression model using statsmodels Logit (not scikit-learn, for coefficient interpretability) predicting deal_closed from features including company_size_employees, industry_vertical, website_visits_30d, email_open_rate, demo_completed, and champion_identified, reports the model summary with odds ratios (exponentiated coefficients), 95% confidence intervals, and p-values, evaluates model performance using ROC-AUC and a calibration curve to verify predicted probabilities are reliable, and generates a lead score formula expressed as a weighted point system that a sales rep can apply manually in a CRM.","tags":["statistics","logistic-regression","lead-scoring","statsmodels","b2b"],"author":"AINOW","created":"2024-02-15T12:10:00Z","featured":false},

  {"id":"da-28","title":"Price Elasticity Estimation with OLS Regression","prompt":"You are a pricing data scientist at a 380-person online retailer using Python with numpy, pandas, and statsmodels. The pricing team wants to estimate price elasticity of demand for three product categories (Electronics, Apparel, Home & Garden) using six months of weekly price and quantity data. Write a Python script that log-transforms both price and quantity to linearize the elasticity relationship, fits separate OLS regression models for each category using statsmodels, extracts the price coefficient as the elasticity estimate with its 95% confidence interval and p-value, tests the null hypothesis that elasticity equals -1 (unit elastic) using a t-test on the coefficient, and produces a formatted comparison table showing estimated elasticity, confidence interval, and whether each category is elastic (|e| > 1), inelastic (|e| < 1), or unit elastic, with a pricing recommendation for each.","tags":["statistics","price-elasticity","ols","hypothesis-testing","statsmodels"],"author":"AINOW","created":"2024-02-15T12:15:00Z","featured":false},

  {"id":"da-29","title":"VIF Diagnosis and Ridge Regression Comparison","prompt":"You are a data analyst at a 190-person real estate analytics company using Python with pandas, statsmodels, and scikit-learn. You have built an OLS model predicting property_sale_price using 12 features including square_footage, lot_size, num_bedrooms, num_bathrooms, garage_spaces, and age_of_property, but the model's coefficient estimates seem unstable and counterintuitive. Write a Python diagnostic script that computes the Variance Inflation Factor (VIF) for all predictors using statsmodels variance_inflation_factor, plots a correlation heatmap to identify which feature pairs have Pearson |r| > 0.7, applies Ridge Regression using scikit-learn with cross-validated alpha selection via RidgeCV to compare coefficient stability against OLS, and produces a side-by-side comparison of OLS vs. Ridge coefficients showing which variables change sign or magnitude dramatically, with a recommendation on which predictors to drop or combine.","tags":["statistics","multicollinearity","ridge-regression","vif","statsmodels"],"author":"AINOW","created":"2024-02-15T12:20:00Z","featured":false},

  {"id":"da-30","title":"Mann-Whitney Test for Skewed Delivery Time Comparison","prompt":"You are a data analyst at a 270-person marketplace platform using Python and scipy. The operations team wants to compare median delivery times between two fulfillment partners, but delivery_time_minutes is heavily right-skewed and does not meet the normality assumptions for a t-test. Write a Python script that first verifies non-normality using the Shapiro-Wilk test and QQ plot for both samples, applies the Mann-Whitney U test using scipy.stats.mannwhitneyu with alternative='two-sided' to compare the distributions, computes the rank-biserial correlation as the effect size measure, calculates the 95% confidence interval for the median difference using bootstrap resampling with 5,000 iterations, and generates a side-by-side box-and-whisker plot with individual data points overlaid as a jitter strip. Conclude with a recommendation for which fulfillment partner to prioritize based on statistical and operational evidence.","tags":["statistics","non-parametric","mann-whitney","scipy","delivery-analytics"],"author":"AINOW","created":"2024-02-15T12:25:00Z","featured":false},

  // --- 4. PYTHON DATA ANALYSIS (da-31 to da-40) ---
  {"id":"da-31","title":"Pandas Pipeline for Monthly Revenue Reconciliation","prompt":"You are a finance data analyst at a 320-person SaaS company. Each month you reconcile revenue data extracted from Stripe, NetSuite, and Salesforce, which arrive as three separate CSV files with inconsistent column names, date formats, and currency representations. Write a pandas pipeline using method chaining that: reads all three CSVs, renames columns to a canonical schema using a mapping dictionary, parses date columns with pd.to_datetime using the appropriate format strings, converts all monetary values from string format (e.g. '$1,234.56') to float64 using str.replace and astype, outer-joins the three DataFrames on deal_id, adds a reconciliation_flag column marking rows where Stripe amount and NetSuite amount differ by more than $0.01, and exports the flagged rows to a separate Excel file with conditional formatting highlighting discrepancies in red using openpyxl.","tags":["python","pandas","reconciliation","finance","etl"],"author":"AINOW","created":"2024-02-15T12:30:00Z","featured":false},

  {"id":"da-32","title":"Matplotlib Four-Panel Executive Weekly Report","prompt":"You are a senior analyst at a 500-person retail company. Every Monday you produce a four-panel matplotlib figure for the executive team's weekly briefing covering: (1) daily revenue for the past 30 days as a line chart with a 7-day rolling average overlay, (2) top 10 product categories by week-over-week revenue change as a horizontal bar chart with red/green coloring, (3) geographic sales by region as a bar chart with prior-week comparison, and (4) conversion funnel metrics as a waterfall chart. Write a Python script using matplotlib subplots with a 2x2 grid, consistent corporate color palette (hex codes defined as constants at the top), bold titles with data-as-of date, and annotations marking the highest and lowest daily revenue points on the time series. The script should accept the current week's date as a command-line argument and save the figure as a PNG to a reports/ directory.","tags":["python","matplotlib","reporting","executive","visualization"],"author":"AINOW","created":"2024-02-15T12:35:00Z","featured":false},

  {"id":"da-33","title":"Reusable Seaborn Visualization Module for Sales Pipelines","prompt":"You are a sales operations analyst at a 240-person B2B software company using Python with seaborn and matplotlib. You need to build a reusable visualization module that any analyst can call to profile a sales pipeline DataFrame. Write a Python module with four functions: plot_deal_size_distribution() that generates a seaborn histplot with KDE and vertical lines at mean and median; plot_stage_conversion_funnel() that creates a seaborn barplot of stage-to-stage conversion rates with error bars; plot_rep_performance_boxplot() that shows deal size distribution per sales rep using a seaborn boxplot sorted by median; and plot_win_rate_heatmap() that displays win rates by industry vertical and deal size bucket as a seaborn heatmap with annotated cell values. Each function should accept a DataFrame and optional filter parameters and save the output to a file path argument.","tags":["python","seaborn","sales-analytics","visualization","modular"],"author":"AINOW","created":"2024-02-15T12:40:00Z","featured":false},

  {"id":"da-34","title":"NumPy Monte Carlo LTV Simulation","prompt":"You are a growth data scientist at a 150-person subscription box company using Python with numpy and pandas. The CFO wants a Monte Carlo simulation of 36-month cumulative LTV for new subscriber cohorts to stress-test revenue projections. Write a Python script using numpy that defines input distributions for monthly churn rate (Beta(2,20)), average monthly revenue per user (Normal(42, 8)), and new subscriber count per month (Poisson(500)), runs 10,000 simulation iterations for a 36-month horizon using vectorized numpy operations (no Python loops), computes the 5th, 25th, 50th, 75th, and 95th percentile LTV paths across simulations, plots the fan chart of percentile bands using matplotlib fill_between, and reports the probability that cumulative 36-month LTV per cohort exceeds $1,500 and the value at risk at the 5th percentile.","tags":["python","numpy","monte-carlo","ltv","simulation"],"author":"AINOW","created":"2024-02-15T12:45:00Z","featured":false},

  {"id":"da-35","title":"scikit-learn Feature Importance Pipeline for Credit Risk","prompt":"You are a data scientist at a 420-person retail bank using Python with scikit-learn and pandas. The risk team wants to understand which features drive a gradient boosting model's credit default predictions before submitting the model for regulatory review. Write a Python script that builds a scikit-learn Pipeline with StandardScaler for numeric features and OneHotEncoder for categorical features in a ColumnTransformer, trains a GradientBoostingClassifier on the credit application dataset, extracts feature importances from the fitted model, maps them back to original feature names through the preprocessing pipeline, generates a horizontal bar chart of the top 20 features sorted by importance using matplotlib, and runs a permutation importance analysis using sklearn.inspection.permutation_importance on the held-out test set to validate that the impurity-based importances are not inflated by high-cardinality features.","tags":["python","scikit-learn","feature-importance","pipeline","credit-risk"],"author":"AINOW","created":"2024-02-15T12:50:00Z","featured":false},

  {"id":"da-36","title":"Z-Score Anomaly Detection on Daily KPI Streams","prompt":"You are a data analyst at a 310-person e-commerce company using Python with pandas and scikit-learn. You own a daily KPI monitoring script that ingests yesterday's metrics (revenue, orders, conversion_rate, average_order_value, cart_abandonment_rate) and flags any metric that has moved anomalously compared to the trailing 28 days of history. Write a Python script that for each KPI: computes the rolling mean and standard deviation over the prior 28 days, calculates a Z-score for yesterday's value, flags the metric as anomalous if |Z| > 2.5, applies a secondary check using the IQR method as confirmation, and generates a formatted Slack-ready alert message using markdown listing only flagged metrics with their current value, 28-day mean, Z-score, and a directional arrow. The script should read from a CSV or BigQuery table and be runnable as a scheduled cron job.","tags":["python","anomaly-detection","kpi-monitoring","automation","pandas"],"author":"AINOW","created":"2024-02-15T12:55:00Z","featured":false},

  {"id":"da-37","title":"Memory-Efficient Large File Processing with Chunking","prompt":"You are a data engineer at a 180-person logistics company using Python and pandas. You receive a daily flat file of 15 million shipment tracking events (~4GB CSV) from a carrier API and need to process it on a machine with 16GB RAM without loading it fully into memory. Write a Python script that uses pd.read_csv with chunksize=500000 to iterate over the file in chunks, applies a filtering step within each chunk to retain only rows where event_type is 'DELIVERED' or 'FAILED', extracts the date component from the event_timestamp column, aggregates counts by carrier_code and event_date within each chunk, accumulates chunk-level results in a list, and concatenates and re-aggregates the list at the end to produce a final daily summary DataFrame. Include timing instrumentation using time.perf_counter and a comparison comment on when to use Dask or Polars instead.","tags":["python","pandas","chunking","large-files","performance"],"author":"AINOW","created":"2024-02-15T13:00:00Z","featured":false},

  {"id":"da-38","title":"K-Means RFM Customer Segmentation with Silhouette Analysis","prompt":"You are a CRM data scientist at a 600-person consumer brand using Python with scikit-learn, pandas, and matplotlib. The marketing team wants to segment customers into actionable groups based on RFM (Recency, Frequency, Monetary) features for targeted campaign personalization. Write a Python script that computes RFM features from raw transaction data using pandas groupby, applies MinMaxScaler to normalize the three features, runs K-Means for k values from 2 to 10 using a loop and stores inertia for an elbow plot, computes silhouette scores for each k value and identifies the optimal k, fits the final K-Means model with optimal k, adds a cluster_label column to the customer DataFrame, generates a 3D scatter plot of the RFM space colored by cluster using matplotlib, and prints a profile table showing mean RFM values per cluster with a suggested marketing label for each segment.","tags":["python","clustering","kmeans","rfm","scikit-learn"],"author":"AINOW","created":"2024-02-15T13:05:00Z","featured":false},

  {"id":"da-39","title":"Support Ticket Clustering with TF-IDF and spaCy","prompt":"You are a customer insights analyst at a 280-person SaaS company using Python with spaCy, pandas, and scikit-learn. The support team receives 2,000 tickets per week and leadership wants to understand the top issue categories without manually tagging every ticket. Write a Python script that loads a CSV of ticket descriptions, applies spaCy's en_core_web_sm model to extract named entities and noun chunks from each ticket body, uses TF-IDF vectorization with sklearn TfidfVectorizer (max_features=500, stop_words='english') to convert tickets to feature vectors, applies K-Means clustering with k=8 clusters, extracts the top 10 TF-IDF terms per cluster as cluster labels, generates a bar chart of ticket volume per cluster, and exports a tagged CSV with original ticket text, cluster_id, and top_terms columns. Include a function to predict the cluster of a new incoming ticket.","tags":["python","nlp","spacy","support-analytics","clustering"],"author":"AINOW","created":"2024-02-15T13:10:00Z","featured":false},

  {"id":"da-40","title":"IoT Time-Series Resampling and Gap Filling","prompt":"You are a data analyst at a 140-person energy monitoring company using Python and pandas. You receive IoT sensor readings at irregular intervals (sometimes every 30 seconds, sometimes with 10-minute gaps) from 200 building energy meters and need to produce clean hourly time series for downstream forecasting models. Write a Python script that for a single meter's DataFrame (columns: timestamp, kwh_reading, meter_id): sets the timestamp as a DatetimeIndex, resamples to 1-hour intervals using resample('1H').sum() to aggregate true consumption, detects gaps where more than 3 consecutive hourly periods are missing, applies forward-fill for gaps of 1-2 periods and linear interpolation for gaps of 3-6 periods using pandas interpolate(method='linear', limit=6), flags gaps longer than 6 hours as data_quality='IMPUTED_LONG_GAP' requiring manual review, and generates a matplotlib time series plot highlighting imputed regions in orange.","tags":["python","pandas","time-series","resampling","iot"],"author":"AINOW","created":"2024-02-15T13:15:00Z","featured":false},

  // --- 5. BUSINESS INTELLIGENCE & DASHBOARDS (da-41 to da-50) ---
  {"id":"da-41","title":"Executive Revenue Dashboard Design in Looker","prompt":"You are a senior BI analyst at a 400-person e-commerce company using Looker connected to BigQuery. The CRO has requested a single-page executive dashboard covering the five most important revenue metrics reviewed weekly. Design the complete Looker dashboard specification including: five hero KPI tiles (Gross Revenue, Net Revenue, Orders, Average Order Value, Return Rate) each showing current week value, week-over-week change percentage, and a 12-week sparkline; a time-series line chart comparing Gross vs. Net Revenue over the trailing 52 weeks with a toggle for weekly and monthly granularity; a treemap of revenue by product category; a geographic bar chart of revenue by top 10 countries; and a cohort heat table showing new customer acquisition by week. Include Looker LookML dimension and measure references for each tile and specify the drill-down destinations for each visualization.","tags":["bi","looker","dashboard","executive","ecommerce"],"author":"AINOW","created":"2024-02-15T13:20:00Z","featured":false},

  {"id":"da-42","title":"Tableau Customer Health Score Calculated Fields","prompt":"You are a customer analytics manager at a 350-person B2B SaaS company using Tableau Desktop connected to Snowflake. The CS team needs a Customer Health Score (0-100) computed in Tableau that combines four signals: product_usage_score (40% weight), support_ticket_volume_score (20% weight, inverted), nps_score (25% weight), and contract_renewal_probability (15% weight). Write the complete Tableau calculated field syntax for each sub-score normalization (scaling raw values to 0-100 using MIN/MAX normalization with fixed business-defined bounds), the composite health score formula, and a second calculated field that maps the score to a RAG status (Red below 40, Amber 40-69, Green 70 and above). Include a parameter for adjusting the product_usage_score weight and the corresponding formula modification. Specify the color encoding logic for a scatter plot showing health score vs. contract_value.","tags":["bi","tableau","calculated-fields","customer-health","saas"],"author":"AINOW","created":"2024-02-15T13:25:00Z","featured":false},

  {"id":"da-43","title":"Power BI DAX Measures for Sales Performance","prompt":"You are a BI developer at a 700-person manufacturing company using Power BI with a SQL Server Analysis Services data model. The sales ops team needs six core DAX measures for their monthly sales performance report. Write complete, commented DAX expressions for: (1) Rolling 3-Month Revenue using DATESINPERIOD, (2) Year-over-Year Revenue Growth Percentage using SAMEPERIODLASTYEAR and DIVIDE, (3) Sales Rep Quota Attainment Percentage using a CALCULATE filter on the rep_targets table, (4) Win Rate as won opportunities divided by total closed opportunities using COUNTROWS and CALCULATE with status filters, (5) Average Sales Cycle Length in days using AVERAGEX and DATEDIFF, and (6) Revenue at Risk defined as open pipeline past expected close date using FILTER and TODAY(). Include a note on where each measure should be placed in the data model for optimal query performance.","tags":["bi","power-bi","dax","sales-analytics","manufacturing"],"author":"AINOW","created":"2024-02-15T13:30:00Z","featured":false},

  {"id":"da-44","title":"Three-Level KPI Tree for a Two-Sided Marketplace","prompt":"You are a head of analytics at a 200-person two-sided marketplace connecting freelancers with businesses. The CEO wants a metric framework that connects the north star metric to operational levers that individual teams can influence week-to-week. Design a three-level KPI tree starting from the North Star Metric of Gross Marketplace Value (GMV), decomposing to Level 1 driver metrics (Active Buyers, Active Sellers, Average Transaction Value, Transactions per Active Buyer), then decomposing each Level 1 metric to two Level 2 operational metrics that teams can directly influence. For each metric at all three levels specify: exact calculation formula, data source and table, weekly reporting cadence owner, target-setting methodology (e.g. year-over-year growth or percentile benchmark), and the leading indicator that predicts it 2-4 weeks in advance.","tags":["bi","kpi-design","metrics","marketplace","strategy"],"author":"AINOW","created":"2024-02-15T13:35:00Z","featured":false},

  {"id":"da-45","title":"dbt Metrics Layer for Self-Service Analytics","prompt":"You are an analytics engineer at a 450-person fintech company using dbt Core, BigQuery, and Looker. Business teams are writing their own ad-hoc SQL queries producing inconsistent metric values because there is no single source of truth for definitions. Design a dbt metrics layer implementation plan that covers: defining five core business metrics (monthly_active_users, average_revenue_per_user, 30_day_churn_rate, net_revenue_retention, customer_acquisition_cost) using dbt's metrics YAML syntax with dimensions, time grains, and filters; the dbt model structure (staging, intermediate, mart layers) that the metrics reference; a governance process for adding new metrics including a definition template and peer review checklist; and a Looker integration approach using the dbt Semantic Layer to expose these metrics as trusted dimensions and measures that business analysts can use without writing SQL.","tags":["bi","dbt","metrics-layer","looker","analytics-engineering"],"author":"AINOW","created":"2024-02-15T13:40:00Z","featured":false},

  {"id":"da-46","title":"Real-Time Logistics Operations Command Center","prompt":"You are a BI architect at a 900-person third-party logistics company. The operations command center monitors 5,000 active shipments simultaneously and needs a real-time dashboard refreshing every 60 seconds. Design the complete dashboard architecture and layout specification covering: a live map visualization showing shipment locations by status (In Transit, Delayed, Delivered, Exception) with color coding; four top-row KPI tiles for On-Time Delivery Rate, Active Exceptions, Average Hours Late, and Deliveries Completed Today with delta vs. yesterday; a drill-down table of all shipments in Exception status sortable by hours_delayed, carrier, and customer_tier; a bar chart of on-time performance by carrier updated in real time; and alert logic that triggers a visual red flash on the exceptions tile when the exception count increases by more than 10% in a 15-minute window. Specify the data refresh mechanism (streaming vs. polling), the recommended BI tool, and the underlying data pipeline architecture.","tags":["bi","real-time","logistics","dashboard","architecture"],"author":"AINOW","created":"2024-02-15T13:45:00Z","featured":false},

  {"id":"da-47","title":"Looker Studio Google Ads Monthly Client Report","prompt":"You are a paid media analyst at a 120-person digital marketing agency managing $2M monthly in Google Ads spend across 15 client accounts. You use Looker Studio connected to the Google Ads API. Design a monthly client performance report template that includes: an account summary scorecard with impressions, clicks, conversions, cost, CPC, CPL, and ROAS for the current month vs. prior month with percentage change indicators; a campaign-level performance table sortable by ROAS with conditional formatting highlighting campaigns below target ROAS in red; a daily spend vs. conversions dual-axis time series chart; a search term analysis table showing top 20 terms by spend with quality score and conversion rate; and a budget pacing chart showing cumulative spend vs. linear budget burn rate. Specify the calculated fields needed for ROAS, CPL variance, and budget pacing percentage, and include the data blend configuration for combining campaign and conversion data.","tags":["bi","looker-studio","google-ads","paid-media","reporting"],"author":"AINOW","created":"2024-02-15T13:50:00Z","featured":false},

  {"id":"da-48","title":"Power BI Row-Level Security for Multi-Region Sales","prompt":"You are a BI developer at a 1,500-person enterprise software company using Power BI Premium. The global sales dashboard contains deal-level pipeline data that regional VPs should only see for their own regions, while the CRO sees all data. Design the complete Row-Level Security (RLS) implementation including: the DAX filter expression for the RegionSecurity role that filters the deals table using USERNAME() to look up the user's assigned regions from a separate user_region_mapping table; a second CRO_AllAccess role with no filter applied; the Power BI Service configuration steps for assigning Azure Active Directory security groups to each role; a testing procedure to verify RLS is working correctly by impersonating each role in Power BI Desktop; and a documentation template for maintaining the user_region_mapping table as team members join, leave, or change regions, specifying who owns the table and the SLA for access updates.","tags":["bi","power-bi","row-level-security","enterprise","governance"],"author":"AINOW","created":"2024-02-15T13:55:00Z","featured":false},

  {"id":"da-49","title":"Dashboard Redesign Critique and Specification","prompt":"You are a senior data visualization specialist at a 300-person healthcare analytics company. [Paste your analysis results or visualization] Review the dashboard described or shown above and produce a comprehensive redesign critique and specification. Your critique must cover: chart type appropriateness (identify any pie charts with more than 5 slices, dual-axis charts with mismatched scales, or 3D charts that distort perception), color usage (check for non-colorblind-safe palettes, gratuitous use of color rather than to encode data), cognitive load assessment (number of distinct data series, presence of chartjunk and grid lines), and mobile responsiveness. Then provide a full redesign specification for each panel: recommended chart type with rationale, color palette with hex codes (using ColorBrewer qualitative schemes), simplified layout, and annotation strategy to guide the reader to the key insight without requiring interpretation.","tags":["bi","data-visualization","dashboard-design","accessibility","best-practices"],"author":"AINOW","created":"2024-02-15T14:00:00Z","featured":false},

  {"id":"da-50","title":"Dynamic Alerting Thresholds for BI Metrics","prompt":"You are a BI platform engineer at a 550-person travel tech company using Looker and BigQuery. The analytics team is overwhelmed by false-positive metric alerts because current thresholds are static and do not account for weekday/weekend patterns or seasonal trends. Design a dynamic alerting system specification that covers: a BigQuery SQL procedure that computes dynamic alert thresholds for each KPI by fitting a seasonal decomposition to 90 days of history and setting upper and lower bounds at mean plus or minus 2 standard deviations of the residuals; a Looker Alert configuration using the Looker API to programmatically update threshold values nightly; an alert routing logic that sends Slack notifications for anomalies during business hours and PagerDuty escalations only when revenue-critical metrics breach thresholds during off-hours; and a feedback loop mechanism where analysts can mark false positives in a Looker dashboard to inform threshold recalibration. Include the BigQuery SQL skeleton for the threshold computation procedure.","tags":["bi","alerting","anomaly-detection","looker","bigquery"],"author":"AINOW","created":"2024-02-15T14:05:00Z","featured":false},

  // --- 6. MACHINE LEARNING APPLICATIONS (da-51 to da-60) ---
  {"id":"da-51","title":"XGBoost Churn Model with SHAP Explainability","prompt":"You are a data scientist at a 400-person telecom company using Python with XGBoost, scikit-learn, and SHAP. The retention team needs a monthly churn prediction model that scores all 200,000 active subscribers and can explain why each customer received their churn probability score. Write a Python script that: preprocesses the features DataFrame using a scikit-learn Pipeline with ColumnTransformer for numeric imputation and scaling and categorical encoding; trains an XGBClassifier with early stopping on a validation set and hyperparameter tuning using Optuna for max_depth, learning_rate, and n_estimators; evaluates the model using ROC-AUC, precision-recall AUC, and a confusion matrix at the 0.4 probability threshold; generates SHAP waterfall plots for the three customers with the highest churn probability to explain individual predictions; and exports a scored customer DataFrame with churn_probability, churn_decile, top_3_contributing_features, and recommended_retention_action columns.","tags":["ml","xgboost","churn","shap","explainability"],"author":"AINOW","created":"2024-02-15T14:10:00Z","featured":true},

  {"id":"da-52","title":"LightGBM Demand Forecasting with Feature Engineering","prompt":"You are a machine learning engineer at a 650-person grocery retailer using Python with LightGBM, pandas, and scikit-learn. The supply chain team needs daily SKU-level demand forecasts 14 days ahead for the top 500 SKUs across 50 stores. Write a Python script that: builds a feature engineering function generating lag features (1, 7, 14-day lags), rolling mean features (7-day and 28-day windows), day-of-week and week-of-year cyclical encodings using sine and cosine transforms, and binary holiday indicators using the holidays library; trains a LightGBMRegressor in a recursive multi-step forecasting framework using TimeSeriesSplit with 5 folds for cross-validation; evaluates with MAPE and RMSE per SKU-store combination; generates a 14-day forecast DataFrame with prediction intervals estimated from quantile regression using LightGBM's quantile objective at the 10th and 90th percentiles; and exports the forecast in the format required by the replenishment system.","tags":["ml","lightgbm","forecasting","feature-engineering","supply-chain"],"author":"AINOW","created":"2024-02-15T14:15:00Z","featured":false},

  {"id":"da-53","title":"Gaussian Mixture Model for Insurance Risk Segmentation","prompt":"You are a data scientist at a 280-person insurance company using Python with scikit-learn, pandas, and matplotlib. The actuarial team needs a probabilistic customer segmentation that captures overlapping risk profiles better than hard K-Means clusters, because some customers genuinely sit between segment boundaries. Write a Python script that: engineers five features from the policy and claims database (claims_frequency, average_claim_severity, policy_tenure_years, coverage_breadth_score, payment_reliability_score); applies StandardScaler normalization; fits Gaussian Mixture Models for n_components from 2 to 8 and selects the optimal number using BIC and AIC scores plotted on a comparison chart; fits the final GMM and extracts soft cluster membership probabilities for each customer; generates a parallel coordinates plot colored by highest-probability segment; and produces a segment profile table showing mean feature values, segment size, and a risk tier label (Low, Medium, High, Very High) with actuarial rationale for the labeling.","tags":["ml","clustering","gaussian-mixture-models","insurance","segmentation"],"author":"AINOW","created":"2024-02-15T14:20:00Z","featured":false},

  {"id":"da-54","title":"Collaborative Filtering Book Recommendation Engine","prompt":"You are a machine learning engineer at a 200-person online bookstore using Python with the Surprise library and pandas. The product team wants a 'Customers also bought' recommendation feature using collaborative filtering on the purchase history of 500,000 customers and 80,000 titles. Write a Python script that: loads purchase data and constructs an explicit ratings matrix using purchase count as an implicit rating proxy with a log1p transformation; trains and evaluates three Surprise algorithms (SVD, SVDpp, KNNWithMeans) using 5-fold cross-validation with RMSE and MAE as metrics; selects the best model and generates top-10 book recommendations for a target user_id filtering out already-purchased items; implements a popularity-based fallback for cold-start users with fewer than 3 purchases; and evaluates recommendation diversity using intra-list diversity (average pairwise cosine distance between recommended items' genre vectors). Include an explanation of how to retrain the model incrementally without reprocessing the full dataset.","tags":["ml","recommendation","collaborative-filtering","surprise","ecommerce"],"author":"AINOW","created":"2024-02-15T14:25:00Z","featured":false},

  {"id":"da-55","title":"Multiclass Text Classification for Support Ticket Routing","prompt":"You are an ML engineer at a 350-person HR technology company using Python with scikit-learn and sentence-transformers. The support team manually routes 1,500 tickets per week to one of eight specialist teams (Payroll, Benefits, Onboarding, Compliance, Technical, Billing, Account Management, Other). Write a Python script that: uses a pre-trained sentence-transformers model (all-MiniLM-L6-v2) to encode ticket text into 384-dimensional embeddings rather than TF-IDF to capture semantic meaning; trains a multiclass LogisticRegression classifier on 12,000 labeled historical tickets with stratified 80/10/10 train/val/test splits; evaluates using macro F1-score, a full sklearn classification_report, and a seaborn confusion matrix heatmap normalized by true class; tunes the regularization parameter C using GridSearchCV; and builds an inference function that accepts a new ticket string and returns the predicted team, confidence score, and a LOW_CONFIDENCE flag when the top predicted class probability is below 0.65, triggering human review.","tags":["ml","text-classification","sentence-transformers","nlp","support"],"author":"AINOW","created":"2024-02-15T14:30:00Z","featured":false},

  {"id":"da-56","title":"Autoencoder Anomaly Detection for Portfolio Returns","prompt":"You are a quantitative data scientist at a 500-person asset management firm using Python with TensorFlow/Keras and pandas. The risk team needs to detect anomalous trading days in multi-asset portfolio returns data that cannot be captured by simple statistical thresholds due to complex inter-asset correlations. Write a Python script that: normalizes a 10-year daily returns matrix (50 assets) using StandardScaler; builds a TensorFlow/Keras autoencoder with encoder layers [50, 32, 16] and decoder layers [16, 32, 50] using ReLU activations and a linear output layer; trains on pre-2020 data using MSE loss, Adam optimizer, batch_size=32, and early stopping with patience=10; computes reconstruction error (MSE per day) on the full dataset; flags days where reconstruction error exceeds the 99th percentile of training-period errors as anomalies; plots reconstruction error as a time series with anomalous days marked as red vertical lines; and validates that detected anomalies correspond to known market stress dates.","tags":["ml","autoencoder","anomaly-detection","finance","tensorflow"],"author":"AINOW","created":"2024-02-15T14:35:00Z","featured":false},

  {"id":"da-57","title":"Production Feature Engineering Pipeline with Feature-engine","prompt":"You are a data scientist at a 220-person proptech company using Python with Feature-engine, scikit-learn, and pandas. You are preparing a feature set for an XGBoost model predicting property rental price and need a production-ready feature engineering pipeline that can be serialized and applied to new listings at inference time. Write a Python script that uses Feature-engine transformers in a scikit-learn Pipeline to: apply WinsorizationTransformer to cap outliers in square_footage and price_per_sqft at 1st and 99th percentiles; use MeanEncoder for neighborhood and property_type high-cardinality categoricals; apply CyclicalEncoder to month_listed for seasonality; create interaction features between bedrooms and bathrooms and between square_footage and floor_number using MathFeatures; add DatetimeFeatures to extract days_since_last_renovation and days_on_market; and fit_transform the full pipeline on training data, pickle it, and demonstrate loading and applying it to a new listing row.","tags":["ml","feature-engineering","feature-engine","pipeline","proptech"],"author":"AINOW","created":"2024-02-15T14:40:00Z","featured":false},

  {"id":"da-58","title":"Cross-Sell Propensity Model with SMOTE for Imbalanced Classes","prompt":"You are a data scientist at a 600-person retail bank using Python with scikit-learn and imbalanced-learn. You are building a model to identify checking account customers likely to take out a personal loan in the next 90 days. The positive class (bought loan) represents only 3% of the training data. Write a Python script that: establishes a stratified 70/15/15 train/validation/test split preserving class imbalance; applies SMOTE oversampling from imbalanced-learn only to the training set to achieve a 1:5 positive-to-negative ratio; trains a Random Forest and a LightGBM model; compares both models using the Precision-Recall curve and PR-AUC (not ROC-AUC, which is misleading for imbalanced data) on the test set; selects the optimal classification threshold by maximizing F-beta score (beta=0.5 to favor precision) using the validation set; generates a decile lift chart showing model lift vs. random baseline; and exports a scored customer file with propensity score, recommended action, and estimated expected revenue from conversion.","tags":["ml","imbalanced-classes","smote","cross-sell","banking"],"author":"AINOW","created":"2024-02-15T14:45:00Z","featured":false},

  {"id":"da-59","title":"ML Model Monitoring Pipeline with Evidently and MLflow","prompt":"You are an MLOps engineer at a 380-person insurance company using Python, Evidently AI, and MLflow. A churn prediction model deployed six months ago is suspected to be degrading due to feature drift in post-pandemic customer behavior data. Write a Python script that uses the Evidently library to: compute a DataDriftReport comparing the model's training data distribution against the last 30 days of production scoring data across all 25 input features; identify features with PSI (Population Stability Index) above 0.2 as High Drift and 0.1-0.2 as Moderate Drift; generate a ModelPerformanceReport comparing predicted churn probabilities from the current model versus a challenger model retrained on recent data; log all drift metrics to MLflow as run metrics with timestamps; and trigger a retraining workflow flag (write to a status table in PostgreSQL) when more than 5 features show High Drift or when Brier Score on recent labeled data exceeds 0.18.","tags":["ml","mlops","model-monitoring","evidently","drift-detection"],"author":"AINOW","created":"2024-02-15T14:50:00Z","featured":false},

  {"id":"da-60","title":"Equipment Failure Prediction with tsfresh Time-Series Features","prompt":"You are a machine learning engineer at a 450-person industrial manufacturing company using Python with tsfresh, scikit-learn, and pandas. Maintenance engineers want a model that predicts equipment failure 48 hours in advance using multivariate sensor time series (temperature, vibration, pressure, current_draw sampled at 1-minute intervals). Write a Python script that: uses tsfresh to automatically extract comprehensive features from rolling 24-hour windows of the four sensor signals, applying the MinimalFCParameters setting for speed on a 2-million-row dataset; filters extracted features using tsfresh's benjamini_hochberg FDR correction; trains a GradientBoostingClassifier with class_weight='balanced' to handle the 95/5 class imbalance; evaluates using F1-score and recall (missing a failure is more costly than a false alarm) and plots an ROC curve; and implements a sliding window inference function that takes the last 24 hours of live sensor data and returns a failure_probability and hours_of_margin estimate.","tags":["ml","time-series-classification","predictive-maintenance","tsfresh","manufacturing"],"author":"AINOW","created":"2024-02-15T14:55:00Z","featured":false},

  // --- 7. DATA STORYTELLING & COMMUNICATION (da-61 to da-70) ---
  {"id":"da-61","title":"Executive Summary for an Inconclusive A/B Test","prompt":"You are a senior product analyst at a 300-person e-commerce company. You ran a 30-day A/B test on a new product recommendation algorithm that was expected to increase revenue per session by 5%. The test result showed a +1.2% lift with a p-value of 0.18 — statistically inconclusive. The VP of Product has limited statistics training and is frustrated that three weeks of engineering effort produced no clear winner. Write a 400-word executive summary structured as: (1) What we tested and why, (2) What the data showed — including the confidence interval, observed power, and minimum detectable effect in plain English without jargon, (3) What this means for the roadmap — specifically whether to abandon the feature, extend the test, or reframe the hypothesis, and (4) Recommended next action with a specific timeline. Avoid the phrases 'statistically significant' and 'p-value' in the body — instead use language a business audience understands about certainty and evidence strength.","tags":["storytelling","executive-communication","ab-test","product","reporting"],"author":"AINOW","created":"2024-02-15T15:00:00Z","featured":false},

  {"id":"da-62","title":"SCQA Data Narrative for Board Retention Presentation","prompt":"You are the head of analytics at a 500-person subscription software company preparing the quarterly board presentation. The CFO will present revenue metrics and wants your analysis of a declining net revenue retention trend from 112% to 104% over three quarters woven into a compelling narrative. Write a data narrative framework for a 6-slide board sequence using the SCQA framework (Situation, Complication, Question, Answer), specifying for each slide: the single headline insight as a full sentence (not a topic label), which chart to show and why that chart type best encodes the data, what data annotation to add to guide the audience to the key takeaway, which supporting metrics to mention verbally vs. put on the slide, and a transition sentence to the next slide. The narrative should build to a clear strategic recommendation with confidence levels for three possible interventions.","tags":["storytelling","board-presentation","narrative","scqa","executive"],"author":"AINOW","created":"2024-02-15T15:05:00Z","featured":false},

  {"id":"da-63","title":"Translating Model Performance Metrics into Business Language","prompt":"You are a data scientist at a 250-person retail bank. You have run a logistic regression predicting loan default and your model summary shows: AUC-ROC 0.82, Gini coefficient 0.64, KS statistic 0.48, and a Brier score of 0.09. The credit risk committee attending your presentation includes the CFO, the Chief Risk Officer, and three regional lending managers — none of whom have statistics backgrounds. [Paste your analysis results or visualization] Write a one-page plain-English model performance summary suitable for a board pack that explains what each metric means using an analogy, translates the AUC of 0.82 into a concrete business statement about how much better the model performs than a random baseline, quantifies the business impact in terms of expected reduction in non-performing loans if the model is used to decline the bottom 20% of applicants by score, and identifies the one metric the committee should monitor monthly as the model operates in production.","tags":["storytelling","statistical-translation","credit-risk","executive","model-performance"],"author":"AINOW","created":"2024-02-15T15:10:00Z","featured":false},

  {"id":"da-64","title":"Dashboard Annotation Strategy for iOS 15 CTR Drop","prompt":"You are a marketing analytics lead at a 180-person DTC consumer brand. Your Looker dashboard shows a sharp 34% drop in email click-through rate in week 32 that the marketing team has not noticed because they are focused on the absolute revenue number. Design a data annotation and insight surfacing strategy for the dashboard that covers: the specific annotation to add to the week 32 data point (exact text, format, and placement), a written explanation to add to the dashboard's insight panel connecting the CTR drop to the iOS 15 Mail Privacy Protection rollout (with supporting data showing the spike in open rate as confirmation of tracking inflation), a recommendation tile showing the three metrics that should replace CTR as primary email engagement KPIs post-iOS15 (clicks per delivered, reply rate, downstream conversion rate), and a style guide for dashboard annotations distinguishing between Data Events (observable facts), Causal Hypotheses (probable explanations), and Action Recommendations (suggested responses).","tags":["storytelling","dashboard-annotation","marketing","ios15","insight-design"],"author":"AINOW","created":"2024-02-15T15:15:00Z","featured":false},

  {"id":"da-65","title":"Five-Act Data Story for a Feature Launch Post-Mortem","prompt":"You are a product analytics manager at a 220-person mobile app company. A major new feature launched three months ago with high internal expectations but adoption reached only 18% of active users versus the 45% target. You need to present the post-mortem analysis to the product and engineering leadership team in a way that is honest about the miss but constructive about learnings. Write a 500-word data story structured in five acts: (1) The Setup — what success was supposed to look like and why, (2) The Reveal — where the metrics diverged from forecast and when the gap first appeared, (3) The Investigation — two to three data-driven hypotheses tested to explain low adoption (e.g., discovery problem vs. value problem vs. UX friction) with the evidence for each, (4) The Verdict — which hypothesis the data most strongly supports with a confidence level, (5) The Pivot — specific, measurable changes to the feature or go-to-market approach with projected adoption impact. Avoid blame language and frame each finding as a learning signal.","tags":["storytelling","post-mortem","product","adoption","data-narrative"],"author":"AINOW","created":"2024-02-15T15:20:00Z","featured":false},

  {"id":"da-66","title":"Monthly Business Review Template Design","prompt":"You are a senior analytics manager at a 600-person B2B software company. The monthly business review currently runs 90 minutes and the leadership team spends most of the time debating which numbers are correct rather than making decisions. Design a complete MBR report template that: opens with a one-page executive scorecard covering eight KPIs (ARR, net new ARR, net revenue retention, churn rate, CAC, LTV, pipeline coverage, and product qualified leads) each with current month value, prior month value, MoM change, and RAG status against target; includes a 'What changed and why' narrative section of no more than 150 words identifying the two most significant positive and two most significant negative metric movements with root-cause hypotheses; adds a 'Decisions needed' section listing three specific choices leadership must make this month with supporting data for each option; and specifies data ownership (which team provides each number), freeze dates, and the review process to ensure all numbers are agreed before the meeting.","tags":["storytelling","business-review","reporting","saas","leadership"],"author":"AINOW","created":"2024-02-15T15:25:00Z","featured":false},

  {"id":"da-67","title":"Chart Selection Guide for Twelve Analytics Questions","prompt":"You are a data visualization lead at a 350-person analytics consultancy. You are creating an internal reference guide to help junior analysts choose the right chart type for twelve common analytics questions. For each of the following question types, specify the recommended primary chart type, one acceptable alternative, one chart type to avoid and why, the maximum number of data series before the chart becomes unreadable, and a worked example with synthetic data: (1) How does metric X trend over time? (2) How do categories rank against each other? (3) What is the composition of a whole? (4) Is there a correlation between X and Y? (5) How is this metric distributed? (6) How do two distributions compare? Include a decision tree flowchart description (text-based, using indented branching logic) that guides an analyst from their question type to the correct chart choice in under 30 seconds.","tags":["storytelling","chart-selection","data-visualization","training","best-practices"],"author":"AINOW","created":"2024-02-15T15:30:00Z","featured":false},

  {"id":"da-68","title":"SCR Insight Bullets from Raw Analysis Output","prompt":"You are a data analyst at a 400-person retail company. [Paste your analysis results or visualization] You have the raw output above from a Python analysis or a set of dashboard screenshots. Transform this analytical output into five insight bullets formatted for a weekly leadership Slack update. Each bullet must follow the SCR structure: Situation (one clause of context), Complication (what changed or is surprising), Resolution (what it means or what to do). Bullets must include specific numbers rounded to one decimal place, avoid analyst jargon (no abbreviations like YoY or QoQ — spell them out), use active voice, start with the most important finding, and be scannable in 90 seconds. After the five bullets, add a single 'Watch list' item: one metric that is not yet alarming but warrants monitoring next week, with the specific threshold that would trigger escalation.","tags":["storytelling","insight-writing","communication","slack","reporting"],"author":"AINOW","created":"2024-02-15T15:35:00Z","featured":false},

  {"id":"da-69","title":"Communicating Forecast Uncertainty to a CEO","prompt":"You are a forecasting analyst at a 280-person travel company. You have built a 12-month revenue forecast using a Prophet model that produces a point estimate and 80% confidence interval. The CEO consistently ignores the uncertainty bands and makes decisions as if the point estimate is guaranteed. Write a communication strategy and specific slide design for presenting forecast uncertainty that: replaces the traditional line and confidence band chart with a scenario-based three-column table showing Bear, Base, and Bull cases with probability weights (25/50/25%) and the specific assumptions that differentiate each scenario; includes a 'Forecast track record' chart showing the last six months of forecasts vs. actuals to calibrate the CEO's confidence in the model's accuracy; adds a 'Decision sensitivity' analysis showing which strategic decisions change depending on whether Bear or Bull case materializes; and proposes a monthly forecast review ritual where the CEO signs off on both the point estimate and the range they are willing to plan against, creating shared ownership of uncertainty.","tags":["storytelling","uncertainty","forecasting","executive","communication"],"author":"AINOW","created":"2024-02-15T15:40:00Z","featured":false},

  {"id":"da-70","title":"Dashboard Annotation Style Guide for BI Teams","prompt":"You are a BI standards lead at a 700-person financial services company with twelve analysts building dashboards across five business units. Inconsistent annotation practices are causing confusion: some dashboards have no context, others have paragraphs of text obscuring the charts, and annotations often mix factual observations with unverified opinions. Write a comprehensive dashboard annotation style guide covering: a four-type annotation taxonomy (Data Marker for specific data point callouts, Trend Annotation for directional commentary, Causal Hypothesis for explanations requiring verification, Action Prompt for decision triggers) with a visual example and forbidden phrases for each type; character limits (Data Marker: 12 words max, Trend Annotation: 25 words max); a confidence language ladder replacing vague words with precise ones; formatting standards for font size, color, and placement; and a peer review checklist with five yes/no questions every annotation must pass before a dashboard is published.","tags":["storytelling","annotation","style-guide","bi","governance"],"author":"AINOW","created":"2024-02-15T15:45:00Z","featured":false},

  // --- 8. DATA QUALITY & ENGINEERING (da-71 to da-80) ---
  {"id":"da-71","title":"dbt Test Suite for a Financial Revenue Recognition Mart","prompt":"You are an analytics engineer at a 450-person fintech company using dbt Core with BigQuery. The revenue recognition mart is used by the finance team to close the books and any data quality issue discovered after month-end close causes costly restatements. Write a complete dbt schema.yml configuration for the fct_revenue_recognition model that includes: not_null and unique tests on the transaction_id primary key; an accepted_values test on recognition_method restricted to cash, accrual, and deferred; a relationships test verifying every account_id exists in the dim_accounts model; a custom generic test checking that the sum of recognized_amount within each accounting_period_id matches the corresponding total in the source ERP table within a $0.01 tolerance using a threshold parameter; a dbt-expectations test verifying that recognized_amount is always between 0 and 10,000,000; and model-level and column-level descriptions for every field. Include the packages.yml entry for dbt-expectations.","tags":["data-quality","dbt","testing","finance","analytics-engineering"],"author":"AINOW","created":"2024-02-15T15:50:00Z","featured":false},

  {"id":"da-72","title":"CRM Contact Record Cleaning Pipeline","prompt":"You are a data engineer at a 300-person B2B technology company using Python with pandas and the phonenumbers library. The sales team's CRM has 85,000 contact records accumulated over six years with inconsistent data entry: phone numbers in 12 different formats, email addresses with typos, company names in inconsistent casing, and job titles with 400+ variations that need mapping to 15 standard levels. Write a Python data cleaning module with four functions: clean_phone_numbers() that uses the phonenumbers library to parse and reformat all numbers to E.164 format and flag unrecognizable numbers; clean_email_addresses() that validates format with regex, lowercases everything, and flags suspicious domains; standardize_company_names() that applies title casing, expands common abbreviations, and uses fuzzy matching to deduplicate variants of the same company; and normalize_job_titles() that maps raw titles to a 15-level seniority hierarchy using a configurable lookup dictionary with fuzzy fallback. Each function should return the cleaned column and a quality_report dict.","tags":["data-quality","python","crm","data-cleaning","pandas"],"author":"AINOW","created":"2024-02-15T15:55:00Z","featured":false},

  {"id":"da-73","title":"Airflow DAG for Daily Data Validation Before dbt","prompt":"You are a data platform engineer at a 520-person e-commerce company using Apache Airflow 2.7 with BigQuery as the warehouse. You need a production Airflow DAG that runs daily at 6 AM UTC and validates that overnight data loads completed successfully before downstream dbt models are triggered. Write a complete Airflow DAG definition that: uses a BigQueryCheckOperator to verify that yesterday's orders table partition has at least 5,000 rows and is not more than 50% higher than the 30-day average; uses a BigQueryIntervalCheckOperator to compare yesterday's revenue total to the prior 7-day average and fail if it deviates by more than 30%; sends a Slack notification via SlackWebhookOperator on both success and failure with the check name, result, and a link to the Airflow task log; and only triggers the downstream dbt_run_models TaskGroup if all validation checks pass, using Airflow's ShortCircuitOperator pattern. Include proper retry logic (retries=2, retry_delay=5min) and SLA configuration.","tags":["data-quality","airflow","data-validation","bigquery","pipeline"],"author":"AINOW","created":"2024-02-15T16:00:00Z","featured":false},

  {"id":"da-74","title":"Multi-Tenant SaaS Analytics Schema Design with dbt and Snowflake","prompt":"You are a senior data engineer at a 180-person multi-tenant SaaS company using dbt and Snowflake. You are redesigning the analytics schema to support per-tenant reporting while maintaining a single codebase and without exposing tenant data across boundaries. Design the complete data model architecture covering: the staging layer structure for isolating raw tenant data ingested via Fivetran from per-tenant PostgreSQL databases; the intermediate layer design using a single fct_tenant_events model with tenant_id as a partition key and row-level isolation enforced via Snowflake Row Access Policies; the mart layer structure with tenant-agnostic aggregate models and tenant-specific models for customer-facing analytics; a dbt variable and Jinja macro strategy for parameterizing tenant-specific business logic; and the Snowflake multi-tenant security architecture using separate roles per tenant with least-privilege access, and a procedure for onboarding a new tenant without modifying existing dbt models.","tags":["data-engineering","data-modeling","dbt","snowflake","multi-tenant"],"author":"AINOW","created":"2024-02-15T16:05:00Z","featured":false},

  {"id":"da-75","title":"Great Expectations Suite for E-Commerce Event Stream","prompt":"You are a data quality engineer at a 400-person online retailer using Great Expectations (GX) with a Spark backend reading from an S3 data lake. The product analytics team's core event stream (page_view, add_to_cart, checkout_start, purchase) arrives from Kafka and must be validated before being written to the analytics warehouse. Write a Great Expectations expectation suite definition using the GX 0.17+ fluent API for the raw_events table that includes: expect_column_values_to_not_be_null for event_id, user_id, event_type, and event_timestamp; expect_column_values_to_be_in_set for event_type restricted to the four valid event names; expect_column_values_to_be_between for event_timestamp between 30 days ago and tomorrow using dynamic datetime evaluation; expect_column_pair_values_A_to_be_greater_than_B verifying that checkout_timestamp is always after add_to_cart_timestamp for the same session; and a custom expectation class ExpectDailyEventVolumeToBeWithinRange that checks row count against a configurable min/max band derived from a 14-day rolling average.","tags":["data-quality","great-expectations","event-data","validation","spark"],"author":"AINOW","created":"2024-02-15T16:10:00Z","featured":false},

  {"id":"da-76","title":"Zero-Downtime Schema Migration for a High-Volume PostgreSQL Table","prompt":"You are a data platform engineer at a 250-person logistics company using PostgreSQL 15 and Flyway for schema versioning. The operations team needs to split the monolithic shipments table (currently 800 million rows) into two tables — shipment_headers and shipment_events — without any downtime during the 24/7 operational window. Design a zero-downtime migration strategy that covers: the Flyway versioned migration scripts to create the new tables with appropriate indexes and foreign key constraints; a dual-write trigger on the original shipments table that populates both old and new schemas during the transition period; a backfill strategy using batched UPDATE statements processing 10,000 rows at a time during off-peak hours to avoid lock contention; a verification query set to confirm row counts and checksum consistency between old and new schemas before cutover; the application-level feature flag strategy for switching read queries to the new schema; and a rollback procedure with specific triggers and rollback execution time estimate.","tags":["data-engineering","postgresql","schema-migration","flyway","zero-downtime"],"author":"AINOW","created":"2024-02-15T16:15:00Z","featured":false},

  {"id":"da-77","title":"Column-Level Data Lineage with dbt and OpenLineage","prompt":"You are an analytics engineer at a 600-person healthcare company using dbt Cloud, BigQuery, and Marquez (OpenLineage-compatible metadata server). Regulatory requirements (HIPAA audit trail) demand that every field in the patient_outcomes mart can be traced back to its source system with documentation of every transformation applied. Design the data lineage implementation covering: dbt model configurations using the meta property to attach source_system, pii_classification, and retention_policy tags to every column; the dbt-openlineage integration configuration for emitting run-level lineage events to Marquez after each dbt job; a custom dbt macro that generates a column-level lineage comment block in each model documenting input columns, transformation logic, and output column for every derivation; a Marquez API query script that retrieves the full lineage graph for a specified output column and formats it as a human-readable audit report; and a governance process for ensuring lineage documentation stays current, including a CI check that fails if a modified model's column descriptions are not updated.","tags":["data-engineering","data-lineage","dbt","openlineage","healthcare"],"author":"AINOW","created":"2024-02-15T16:20:00Z","featured":false},

  {"id":"da-78","title":"PII Detection and Masking Pipeline with Presidio","prompt":"You are a data privacy engineer at a 350-person fintech company using Python with the Presidio Analyzer library and pandas. A recent audit found that PII is leaking into three analytics tables through free-text customer notes fields: support_ticket_body, transaction_memo, and application_comments. Write a Python pipeline that: uses Microsoft Presidio Analyzer with the English NLP engine to detect PII entities (PERSON, EMAIL_ADDRESS, PHONE_NUMBER, CREDIT_CARD, US_SSN, IBAN_CODE) in each text column; applies Presidio Anonymizer to replace detected entities with typed placeholders (e.g. PERSON or PHONE_NUMBER) rather than deleting them, to preserve text length for NLP models; processes DataFrames in batches of 1,000 rows to manage memory; logs every detected PII instance (entity type, column, row_id, confidence_score) to a separate audit_log table without storing the actual PII value; produces a summary report by table and entity type showing detection counts and average confidence scores; and includes a unit test suite using pytest with synthetic PII-containing text as fixtures.","tags":["data-quality","pii","presidio","privacy","python"],"author":"AINOW","created":"2024-02-15T16:25:00Z","featured":false},

  {"id":"da-79","title":"Data Contract YAML for Inter-Team Dataset Sharing","prompt":"You are a senior data engineer at a 800-person technology company where the data platform team provides curated datasets to eight consuming teams. Informal agreements about data structure and SLAs keep breaking when upstream teams make schema changes without notice. Write a complete data contract template in YAML format following the Data Contract Specification v0.9 standard for the customer_360 dataset covering: the contract metadata (owner, version, status, effectiveDate); the schema definition with field names, types, constraints, and business descriptions for 10 core customer fields including customer_id, acquisition_date, current_mrr, churn_probability_score, and nps_score; the SLA terms (freshness SLA of data no older than 4 hours, availability SLA of 99.5%, quality SLA requiring zero null customer_id values); the change management terms specifying notice periods for breaking vs. non-breaking changes; and the contact and escalation path for SLA violations.","tags":["data-engineering","data-contracts","governance","schema","sla"],"author":"AINOW","created":"2024-02-15T16:30:00Z","featured":false},

  {"id":"da-80","title":"Incremental dbt Model for 50M-Row Daily Event Processing","prompt":"You are an analytics engineer at a 300-person gaming company using dbt Cloud with BigQuery. The raw_game_events table receives 50 million rows per day and the current full-refresh dbt model for the fct_daily_player_activity mart takes 4 hours to run, blocking the 6 AM dashboard refresh. Rewrite the fct_daily_player_activity model as an incremental dbt model that: uses the incremental materialization with unique_key on player_id and event_date and the merge strategy; defines the incremental filter using dbt's is_incremental() macro to process only events from the last 3 days to handle late-arriving data; includes a partitioning clause on event_date and a clustering configuration on player_id and game_mode for BigQuery query optimization; defines pre-hook SQL to create a staging temp table for the incremental batch; adds a post-hook that runs a row count validation comparing the incremental batch size against the expected range from a metadata table; and documents the full-refresh cadence recommendation (weekly) and the procedure for triggering a manual full-refresh via dbt Cloud API.","tags":["data-engineering","dbt","incremental","bigquery","performance"],"author":"AINOW","created":"2024-02-15T16:35:00Z","featured":false},

  // --- 9. PRODUCT ANALYTICS (da-81 to da-90) ---
  {"id":"da-81","title":"Multi-Step Funnel Analysis with Drop-Off Diagnostics","prompt":"You are a product analyst at a 250-person B2B SaaS company using Mixpanel and BigQuery. The activation funnel has five steps: trial_signup, product_tour_started, first_project_created, team_member_invited, and subscription_upgraded. The VP of Product wants to know not just the conversion rate at each step, but why users drop off — specifically whether drop-off correlates with user role, company size, acquisition source, or device type. Write a BigQuery SQL query and a Python analysis script that: computes overall conversion rates between consecutive funnel steps using a CTE-based approach; segments drop-off rates by user_role (admin, member, viewer), company_size_tier (SMB, Mid-Market, Enterprise), and acquisition_source (organic, paid, partner) for the step with the highest absolute drop-off; runs a chi-squared test to determine which segmentation variable most strongly predicts completion beyond the highest drop-off step; and generates a seaborn FacetGrid of completion rates by segment for the top two predictive variables.","tags":["product-analytics","funnel","bigquery","mixpanel","segmentation"],"author":"AINOW","created":"2024-02-15T16:40:00Z","featured":false},

  {"id":"da-82","title":"Weekly Cohort Retention Heatmap from Amplitude Data","prompt":"You are a growth analyst at a 180-person mobile productivity app using Python with pandas and seaborn, pulling data from Amplitude via their Export API. The growth team reviews weekly cohort retention every Monday to evaluate whether recent product changes have improved D1, D7, and D30 retention. Write a Python script that: queries the Amplitude Export API for event data over the last 90 days and constructs a user-level DataFrame with user_id, cohort_week (first app_open date truncated to Monday), and a set of activity_week columns; reshapes the data into a cohort retention matrix using pandas pivot_table with cohort_week as rows and weeks_since_signup (0 through 12) as columns; computes retention rates as percentages of cohort week 0 size; generates a seaborn heatmap with cohort weeks on the y-axis, weeks since signup on the x-axis, annotated percentage values in each cell, a diverging color scale from red (0%) to green (40%+), and cohort size labels on the right y-axis; and prints a summary identifying the three cohort weeks with the highest and lowest D30 retention for investigation.","tags":["product-analytics","retention","cohort","seaborn","amplitude"],"author":"AINOW","created":"2024-02-15T16:45:00Z","featured":false},

  {"id":"da-83","title":"Mixed-Methods UX Friction Analysis for Checkout","prompt":"You are a product analytics manager at a 160-person e-commerce company using FullStory for session recording and BigQuery for quantitative analysis. The UX team suspects that a recent checkout redesign is causing mobile users to struggle with the address form, based on qualitative session replay observations, but needs quantitative evidence before prioritizing a fix. Design a mixed-methods analysis framework that: defines a quantitative signal — write a BigQuery SQL query computing form_field_rage_clicks, form_field_abandon_rate, and form_completion_time_seconds per device_type and form_field_name using FullStory's BigQuery integration event data; identifies a statistical significance test (chi-squared on abandon rates between mobile and desktop) with the required sample size for 80% power at 0.05 alpha; specifies a session replay sampling strategy using funnel filters and frustration signal scores; and writes a one-page analysis brief template connecting the quantitative signals to qualitative replay observations with a recommendation confidence level.","tags":["product-analytics","ux","fullstory","session-replay","checkout"],"author":"AINOW","created":"2024-02-15T16:50:00Z","featured":false},

  {"id":"da-84","title":"Feature Adoption Metrics Framework for a SaaS Product Team","prompt":"You are a product analytics lead at a 400-person project management SaaS company using Mixpanel, dbt, and Looker. The product team launches 3-4 features per quarter and lacks a standardized way to measure whether features are succeeding. Design a complete feature adoption measurement framework covering: a five-stage adoption funnel for any new feature (Aware, Discovered, Tried, Adopted, Habitual) with specific event definitions and SQL queries for each stage; a standardized 30/60/90-day adoption scorecard template with six metrics: breadth (percentage of eligible accounts that tried the feature), depth (average usage frequency among adopters), stickiness (week-over-week retention of feature users), activation rate (percentage who complete the core value action within first use), expansion signal (correlation with upsell within 90 days), and NPS delta (NPS score difference between adopters and non-adopters); a dbt model structure for computing these metrics consistently across all features; and a threshold-based feature health classification (Struggling, Growing, Succeeding) with team escalation protocols for Struggling features.","tags":["product-analytics","feature-adoption","metrics","dbt","saas"],"author":"AINOW","created":"2024-02-15T16:55:00Z","featured":false},

  {"id":"da-85","title":"Sequential Testing Experimentation Platform Design","prompt":"You are a senior data scientist at a 350-person fintech startup running 15-20 A/B tests simultaneously across web and mobile products. The current ad-hoc experiment setup has no guardrail metrics, suffers from peeking problems, and has no automated stopping rules. Design a production experimentation platform specification covering: experiment configuration schema (YAML format) defining treatment arms, allocation percentages, primary metric, guardrail metrics, minimum detectable effect, and maximum experiment duration; a sequential testing framework using alpha-spending functions (O'Brien-Fleming boundaries) to allow peeking at results daily without inflating Type I error; a CUPED (Controlled-experiment Using Pre-Experiment Data) variance reduction implementation in Python using pre-experiment values of the primary metric as covariates; automated experiment health checks running nightly (sample ratio mismatch test, novelty effect detection via time-trend analysis of treatment effect); and a results reporting template that distinguishes between ship, iterate, and stop decisions based on statistical evidence and business criteria.","tags":["product-analytics","experimentation","ab-testing","cuped","sequential-testing"],"author":"AINOW","created":"2024-02-15T17:00:00Z","featured":false},

  {"id":"da-86","title":"North Star Metric Decomposition with Elasticity Analysis","prompt":"You are a head of product analytics at a 220-person freelance marketplace using Looker and BigQuery. The CEO has chosen 'Successful Engagements per Week' as the North Star Metric. Three product teams (Acquisition, Matching, and Retention) need to understand how their work connects to this NSM and which leading indicators to track in their weekly sprint reviews. Write a complete NSM decomposition document covering: the algebraic decomposition of Successful Engagements into its multiplicative components (Weekly Active Buyers × Buyer-to-Post Rate × Post-to-Match Rate × Match-to-Completion Rate × Completion-to-High-Rating Rate); SQL queries for each component metric pulling from the relevant BigQuery tables; a sensitivity analysis showing which component has the highest elasticity to the NSM based on 12 months of historical data (which 1% improvement in which component produces the largest NSM gain); and a team metric ownership matrix assigning each component to a product team with their owned dials and the leading indicators that predict each component 2-4 weeks ahead.","tags":["product-analytics","north-star-metric","marketplace","decomposition","strategy"],"author":"AINOW","created":"2024-02-15T17:05:00Z","featured":false},

  {"id":"da-87","title":"In-App Survey Analysis for Quarterly Roadmap Prioritization","prompt":"You are a product analyst at a 290-person B2B analytics tool company. You ran a 30-day in-app survey asking 2,400 users to select their top three pain points from a list of 12 options. You need to translate the survey responses into a feature prioritization recommendation for the quarterly roadmap planning session. Write a Python analysis script using pandas and matplotlib that: computes the selection frequency and rank for all 12 pain points with 95% confidence intervals using the Wilson score interval formula; segments responses by user_plan_tier (starter, professional, enterprise) and user_tenure_months (0-3, 3-12, 12+) to identify whether pain points cluster differently by segment; runs a Cochran's Q test to determine if selection proportions differ significantly across segments; generates a 2x2 prioritization matrix (reach vs. intensity) where reach is selection frequency and intensity is the proportion who selected the item as their top choice; and writes a three-paragraph prioritization recommendation identifying the top three features to build, which user segment most urgently needs each, and the business case in terms of churn risk or upsell opportunity.","tags":["product-analytics","survey-analysis","feature-prioritization","python","b2b"],"author":"AINOW","created":"2024-02-15T17:10:00Z","featured":false},

  {"id":"da-88","title":"Onboarding Path Analysis with Sankey Diagram","prompt":"You are a product data analyst at a 200-person HR SaaS company using Heap Analytics and BigQuery. New user onboarding has a 7-step flow and only 31% of users complete all seven steps within 14 days of signup. The product team wants to understand not just where users drop off, but what paths the successful completers take compared to non-completers. Write a BigQuery SQL query and Python analysis that: extracts all onboarding event sequences per user from the Heap events table using STRING_AGG ordered by event_timestamp to build a path string; identifies the top 10 most common paths for completers and top 10 for non-completers using GROUP BY on the path string; computes the median time between consecutive steps for completers vs. non-completers at each step transition; identifies the single step transition with the greatest time difference between completers and non-completers as the highest-leverage intervention point; and generates a Sankey diagram specification (node and link data for a plotly Sankey) showing the flow of users through the onboarding steps with node sizes proportional to user counts.","tags":["product-analytics","onboarding","path-analysis","heap","bigquery"],"author":"AINOW","created":"2024-02-15T17:15:00Z","featured":false},

  {"id":"da-89","title":"Cancellation Survey Analysis with Text Clustering","prompt":"You are a customer analytics analyst at a 320-person subscription streaming company using Python, pandas, and BigQuery. When customers cancel, they complete a 3-question cancellation survey: primary_churn_reason (12 categories), satisfaction_score (1-5), and open_text_feedback. You have 8,000 completed surveys from the last six months. Write a Python analysis that: computes churn reason distribution by frequency and revenue impact (joining survey data with customer LTV from BigQuery); segments churn reasons by subscription_tier, tenure_bucket, and acquisition_cohort to identify which segments are most affected by each reason type; applies TF-IDF and K-Means clustering (k=5) to the open_text_feedback column using scikit-learn to extract thematic clusters from unstructured responses; maps text clusters to the closest structured churn reason categories to validate the taxonomy; generates a dual-axis chart showing churn reason volume (bar) and average customer LTV lost per reason (line); and produces a prioritized win-back opportunity table ranking churn reasons by frequency times average LTV times estimated win-back probability.","tags":["product-analytics","churn-analysis","survey","nlp","python"],"author":"AINOW","created":"2024-02-15T17:20:00Z","featured":false},

  {"id":"da-90","title":"Product-Led Growth Engagement Scoring Model","prompt":"You are a data scientist at a 270-person product-led growth SaaS company using Python, dbt, and Salesforce. The sales team needs an engagement score (0-100) for every free-tier account to prioritize outbound outreach toward accounts showing buying intent signals. Write a Python and dbt implementation plan covering: the dbt model that aggregates 15 product usage signals from the events warehouse into a weekly account_engagement_features table (including active_users_last_7d, features_activated_count, api_calls_last_30d, invites_sent, upgrade_page_views, and support_tickets_opened_inverted); a Python script that trains a logistic regression model predicting trial_converted using the 15 features on 12 months of historical data and extracts the model coefficients as feature weights; a weighted scoring formula that applies the logistic regression coefficients to current-week feature values and scales the output to 0-100 using min-max normalization; a dbt model that applies this scoring formula weekly and pushes scores to Salesforce via the Salesforce Bulk API 2.0; and a calibration chart validating that accounts scoring 80+ convert at the expected rate.","tags":["product-analytics","plg","engagement-scoring","dbt","salesforce"],"author":"AINOW","created":"2024-02-15T17:25:00Z","featured":false},

  // --- 10. ADVANCED ANALYTICS (da-91 to da-100) ---
  {"id":"da-91","title":"Difference-in-Differences Causal Impact of a Loyalty Program","prompt":"You are a senior data scientist at a 600-person retail chain. The company rolled out a new loyalty program in 50 pilot stores in Q2 while 150 control stores kept the existing program. The CEO wants to know the causal impact of the program on weekly revenue — not just the correlation. Write a Python analysis using statsmodels that: verifies the parallel trends assumption by plotting weekly revenue trends for treatment and control stores for the 12 weeks pre-treatment and testing whether the pre-treatment slopes are statistically indistinguishable; implements a difference-in-differences regression model using OLS with store fixed effects, week fixed effects, and a treatment × post_period interaction term as the causal estimator; computes the ATT (Average Treatment Effect on the Treated) with 95% confidence intervals using heteroskedasticity-robust standard errors; runs a placebo test using a fake treatment date 8 weeks before the actual rollout to verify no spurious effect; and presents the results in a causal impact summary table suitable for the board.","tags":["advanced-analytics","causal-inference","diff-in-diff","retail","econometrics"],"author":"AINOW","created":"2024-02-15T17:30:00Z","featured":true},

  {"id":"da-92","title":"Prophet Revenue Forecasting with Promotional Event Effects","prompt":"You are a demand planning data scientist at a 500-person consumer electronics company using Python with the Prophet library and pandas. The finance team needs a 12-month forward revenue forecast with quantified uncertainty intervals, incorporating known future promotional events (Black Friday, Prime Day, product launches) and historical seasonality patterns. Write a Python script that: loads 3 years of weekly revenue data and prepares the Prophet-required ds/y DataFrame format; defines custom seasonality components (weekly, monthly, and quarterly) with appropriate Fourier order settings; adds a holidays DataFrame including all US federal holidays plus five custom company events with configurable window parameters; fits the Prophet model with multiplicative seasonality mode; generates a 52-week forecast with 80% and 95% uncertainty intervals; decomposes the forecast into trend, yearly seasonality, and holiday components using the plot_components() method; and produces a scenario table showing the P10, P50, and P90 forecast for each quarter with the key assumptions driving the spread.","tags":["advanced-analytics","forecasting","prophet","time-series","finance"],"author":"AINOW","created":"2024-02-15T17:35:00Z","featured":false},

  {"id":"da-93","title":"Uplift Modeling for Insurance Win-Back Campaign Targeting","prompt":"You are a data scientist at a 450-person insurance company using Python with scikit-uplift and XGBoost. The retention marketing team sends win-back offers to lapsed customers, but sending to everyone costs $2.40 per contact and many customers would have renewed without the offer. Write a Python uplift modeling pipeline that: splits the training data into treatment (received offer) and control (no offer) groups and defines the four classic uplift segments (Persuadables, Sure Things, Lost Causes, Do Not Disturbs); trains a Two-Model Uplift approach (separate response models for treatment and control) and a Class Variable Transformation single-model approach using XGBClassifier as the base learner; evaluates both models using the Qini curve and Qini coefficient on held-out test data; generates a targeting recommendation table showing expected incremental conversions and ROI at each decile of predicted uplift score; and computes the optimal treatment threshold that maximizes net profit given a $2.40 cost per contact and $85 expected revenue from a converted renewal.","tags":["advanced-analytics","uplift-modeling","causal-ml","marketing","insurance"],"author":"AINOW","created":"2024-02-15T17:40:00Z","featured":false},

  {"id":"da-94","title":"Aspect-Based Sentiment Analysis on Product Reviews","prompt":"You are a product intelligence analyst at a 300-person consumer hardware company using Python with transformers (HuggingFace), pandas, and matplotlib. You have 120,000 Amazon product reviews spanning 4 years for your three flagship products and need to track sentiment trends and extract specific feature-level feedback themes. Write a Python script that: applies the cardiffnlp/twitter-roberta-base-sentiment-latest model from HuggingFace to classify each review into POSITIVE, NEUTRAL, or NEGATIVE in batches of 32 using a GPU-accelerated pipeline; computes monthly sentiment scores as (positive_count minus negative_count) divided by total_count to create a net sentiment index; applies sentence-level aspect-based sentiment analysis using spaCy dependency parsing to extract opinion expressions about specific product aspects (battery_life, build_quality, ease_of_use, connectivity, value); generates a multi-line time series chart of monthly net sentiment per product with vertical lines marking product firmware updates and major competitor launches; and produces an aspect sentiment heatmap showing each product and aspect combination as a color-coded average sentiment score.","tags":["advanced-analytics","nlp","sentiment-analysis","huggingface","product-reviews"],"author":"AINOW","created":"2024-02-15T17:45:00Z","featured":false},

  {"id":"da-95","title":"Synthetic Control Method for Sugar Tax Policy Evaluation","prompt":"You are a data scientist at a 200-person public health analytics company using Python. A state health department wants to evaluate the impact of a sugar tax implemented in one state in January 2023 on per-capita sugary beverage consumption, but there is no randomized control group — only observational data from 49 other states. Write a Python analysis using the Synthetic Control Method that: constructs a weighted combination of donor states (pre-treatment period 2018-2022) that best matches the treated state's pre-treatment beverage consumption trajectory using scipy.optimize; plots the actual vs. synthetic control consumption trends for the 24-month post-treatment period with the treatment gap highlighted; runs a set of placebo tests by applying the synthetic control method to each donor state as if they had the treatment and plots the distribution of placebo gaps vs. the actual treated state gap; computes a p-value as the proportion of placebo gaps larger than the treated state gap; and writes a 200-word policy brief section interpreting the findings for a non-technical government audience.","tags":["advanced-analytics","synthetic-control","causal-inference","public-health","policy"],"author":"AINOW","created":"2024-02-15T17:50:00Z","featured":false},

  {"id":"da-96","title":"Graph Analytics for Customer Network Churn Effects","prompt":"You are a data scientist at a 380-person collaboration software company using Python with NetworkX and pandas. The growth team hypothesizes that users who are connected to more active users in their workplace network have significantly lower churn rates. Write a Python analysis using NetworkX that: constructs a directed graph from the collaboration_events table where nodes are users and edges represent a collaboration event (document co-edit, comment mention, or meeting) in the last 30 days; computes five node-level centrality measures (degree centrality, betweenness centrality, closeness centrality, PageRank, and eigenvector centrality) for all users; merges centrality scores with the user churn outcome (churned within 90 days); runs a logistic regression with each centrality measure as the sole predictor and reports the AUC and odds ratio to identify the most predictive centrality measure for churn; and generates a scatter plot of PageRank score vs. 90-day churn probability (predicted) with user_tier encoded as point color and company_size encoded as point size.","tags":["advanced-analytics","graph-analytics","networkx","churn","network-effects"],"author":"AINOW","created":"2024-02-15T17:55:00Z","featured":false},

  {"id":"da-97","title":"Geo-Spatial Store Location Scoring with Drive-Time Catchments","prompt":"You are a spatial data scientist at a 700-person quick-service restaurant chain using Python with geopandas, shapely, and folium. The real estate team needs a data-driven store location scoring model for evaluating 200 candidate sites across three metro areas. Write a Python analysis that: loads census tract demographic data (population, median income, daytime population) from the US Census API using the census library; loads competitor restaurant locations from a GeoJSON file and computes the nearest competitor distance for each candidate site using geopandas sjoin_nearest; calculates a catchment area polygon for each candidate site using a 5-minute drive-time isochrone via the OpenRouteService API and counts population and competitors within each catchment; builds a composite location score combining population_density (30% weight), daytime_population_density (25% weight), median_income_index (20% weight), competitor_distance_score (15% weight), and traffic_volume_score (10% weight) with min-max normalized inputs; and generates an interactive folium map with color-coded site markers, a popup showing the score breakdown, and a candidate site ranking table exported to Excel.","tags":["advanced-analytics","geospatial","geopandas","location-analytics","retail"],"author":"AINOW","created":"2024-02-15T18:00:00Z","featured":false},

  {"id":"da-98","title":"Bayesian Hierarchical Model for Multi-Location Revenue Forecasting","prompt":"You are a data scientist at a 450-person restaurant group operating 80 locations across 12 cities using Python with PyMC. Each location has between 30 and 200 weeks of sales history, and the finance team wants revenue forecasts that intelligently share information across similar locations rather than treating each independently or assuming all locations are identical. Write a Python script using PyMC that: specifies a Bayesian hierarchical model where each location's weekly revenue is drawn from a Normal distribution with location-specific mean and variance, and location-specific means are drawn from city-level distributions, which are in turn drawn from a global prior (three-level hierarchy); encodes covariates for day_of_week, week_of_year (cyclical), and a binary holiday indicator at the observation level; samples from the posterior using NUTS (No-U-Turn Sampler) with 2 chains, 2,000 draws, and 1,000 tuning steps; assesses convergence using R-hat statistics and trace plots; generates posterior predictive forecasts for 8 weeks ahead per location with 50% and 90% credible intervals; and identifies the three locations with the widest uncertainty intervals as candidates for additional data collection.","tags":["advanced-analytics","bayesian","hierarchical-model","pymc","forecasting"],"author":"AINOW","created":"2024-02-15T18:05:00Z","featured":false},

  {"id":"da-99","title":"SARIMA Model Selection and Diagnostics for Energy Forecasting","prompt":"You are a time-series analyst at a 260-person energy utility company using Python with statsmodels and pmdarima. The operations team needs automated daily electricity demand forecasts for 48-hour ahead planning. You have 5 years of hourly demand data with clear 24-hour intraday cycles, 7-day weekly cycles, and annual seasonality. Write a Python script that: applies auto_arima from pmdarima to automatically select SARIMA(p,d,q)(P,D,Q,m) orders by minimizing AIC across a defined search space (max_p=3, max_q=3, seasonal=True, m=24 for hourly data); validates stationarity using both the Augmented Dickey-Fuller test and KPSS test and applies the appropriate number of differencing steps; checks model residuals using a four-panel diagnostic plot (residual time series, histogram with KDE, QQ plot, and Ljung-Box test p-values for autocorrelation); generates point forecasts and 95% prediction intervals for the next 48 hours; evaluates out-of-sample performance on the last 30 days using MAPE, RMSE, and coverage probability of the prediction intervals; and implements an automated model retraining trigger when rolling 7-day MAPE exceeds 5%.","tags":["advanced-analytics","time-series","arima","sarima","energy"],"author":"AINOW","created":"2024-02-15T18:10:00Z","featured":false},

  {"id":"da-100","title":"Regression Discontinuity Design for Lending Cutoff Analysis","prompt":"You are a senior economist at a 180-person fintech lending company using Python with statsmodels. The company uses a credit score cutoff of 650 to determine loan approval. The credit risk team wants to estimate the causal effect of loan approval on default rates and 12-month income growth among applicants near the cutoff — information that would inform whether the cutoff should be raised or lowered. Write a Python analysis using a Regression Discontinuity Design that: subsets the applicant data to a bandwidth of 50 credit score points on either side of the 650 cutoff; plots the RDD visual diagnostic showing outcome means in score bins on both sides of the cutoff with overlaid linear fits and the discontinuity gap; estimates the Local Average Treatment Effect (LATE) using local linear regression with a triangular kernel; performs a density test (McCrary sorting test) to verify that applicants are not manipulating their scores to just above the cutoff; runs a falsification test using pre-determined baseline covariates (age, employment_status) as outcomes to verify they show no discontinuity at the cutoff; and interprets the LATE estimate in a 150-word policy recommendation for the chief risk officer.","tags":["advanced-analytics","regression-discontinuity","causal-inference","fintech","econometrics"],"author":"AINOW","created":"2024-02-15T18:15:00Z","featured":false}

];
  __exports.dataanalysisPrompts = dataanalysisPrompts;
})();